(5605586, 811346, 100335, '<td valign="top">Underrated in my opinion. I think this should easily have been in top 10.</td>', 'Underrated in my opinion. I think this should easily have been in top 10.', '2009-08-10 03:13:54.000000', NULL, 0),
(5605587, 811342, 34938, '<td valign="top">You are such a legend Irene...thanks for the story behind this. People think this kind of shot is easy, but it is not...so messy and so hard to get a good shot...of course, I was right on the money and picked it as yours...congrats again...</td>', 'You are such a legend Irene...thanks for the story behind this. People think this kind of shot is easy, but it is not...so messy and so hard to get a good shot...of course, I was right on the money and picked it as yours...congrats again...', '2009-08-10 03:14:37.000000', NULL, 0),
